import { useMemo, useRef, useState } from 'react';
import { useSelector } from 'react-redux';
import { selectReadonly } from '~/app/meta/metaSlice';
import EmptyState from '~/components/EmptyState';
import { ButtonWithPlus } from '~/components/Button';
import Modal from '~/components/Modal';
import NamespaceForm from '~/components/namespaces/NamespaceForm';
import NamespaceTable from '~/components/namespaces/NamespaceTable';
import DeletePanel from '~/components/panels/DeletePanel';
import Slideover from '~/components/Slideover';
import { INamespace } from '~/types/Namespace';
import {
  useDeleteNamespaceMutation,
  useListNamespacesQuery
} from './namespacesSlice';

export default function Namespaces() {
  const [showNamespaceForm, setShowNamespaceForm] = useState<boolean>(false);

  const [editingNamespace, setEditingNamespace] = useState<INamespace | null>(
    null
  );

  const [showDeleteNamespaceModal, setShowDeleteNamespaceModal] =
    useState<boolean>(false);
  const [deletingNamespace, setDeletingNamespace] = useState<INamespace | null>(
    null
  );
  const listNamespaces = useListNamespacesQuery();

  const namespaces = useMemo(() => {
    return listNamespaces.data?.namespaces || [];
  }, [listNamespaces]);
  const readOnly = useSelector(selectReadonly);
  const [deleteNamespace] = useDeleteNamespaceMutation();
  const namespaceFormRef = useRef(null);

  return (
    <>
      {/* namespace edit form */}
      <Slideover
        open={showNamespaceForm}
        setOpen={setShowNamespaceForm}
        ref={namespaceFormRef}
      >
        <NamespaceForm
          ref={namespaceFormRef}
          namespace={editingNamespace || undefined}
          setOpen={setShowNamespaceForm}
          onSuccess={() => {
            setShowNamespaceForm(false);
            setEditingNamespace(null);
          }}
        />
      </Slideover>

      {/* namespace delete modal */}
      <Modal
        open={showDeleteNamespaceModal}
        setOpen={setShowDeleteNamespaceModal}
      >
        <DeletePanel
          panelMessage={
            <>
              Are you sure you want to delete the namespace{' '}
              <span className="font-medium text-violet-500">
                {deletingNamespace?.key}
              </span>
              ? This action cannot be undone.
            </>
          }
          panelType="Namespace"
          setOpen={setShowDeleteNamespaceModal}
          handleDelete={() =>
            deleteNamespace(deletingNamespace?.key ?? '').unwrap()
          }
        />
      </Modal>

      <div className="my-10">
        <div className="sm:flex sm:items-center">
          <div className="sm:flex-auto">
            <h3 className="text-xl font-semibold text-gray-700">Namespaces</h3>
            <p className="mt-2 text-sm text-gray-500">
              Namespaces allow you to group your flags, segments and rules under
              a single name
            </p>
          </div>
          <div className="mt-4">
            <ButtonWithPlus
              variant="primary"
              disabled={readOnly}
              title={readOnly ? 'Not allowed in Read-Only mode' : undefined}
              onClick={() => {
                setEditingNamespace(null);
                setShowNamespaceForm(true);
              }}
            >
              New Namespace
            </ButtonWithPlus>
          </div>
        </div>

        <div className="mt-8 flex flex-col">
          {namespaces && namespaces.length > 0 ? (
            <NamespaceTable
              namespaces={namespaces}
              setEditingNamespace={setEditingNamespace}
              setShowEditNamespaceModal={setShowNamespaceForm}
              setDeletingNamespace={setDeletingNamespace}
              setShowDeleteNamespaceModal={setShowDeleteNamespaceModal}
              readOnly={readOnly}
            />
          ) : (
            <EmptyState
              text="New Namespace"
              disabled={readOnly}
              onClick={() => {
                setEditingNamespace(null);
                setShowNamespaceForm(true);
              }}
            />
          )}
        </div>
      </div>
    </>
  );
}

import { expect, test } from '@playwright/test';

test.describe('Namespaces', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
    await page.getByRole('button', { name: 'Continue to Dashboard' }).click();
  });

  test('can create namespace', async ({ page }) => {
    await page.getByRole('link', { name: 'Settings' }).click();
    await page.getByRole('link', { name: 'Namespaces' }).click();
    await expect(
      page.getByRole('heading', { name: 'Namespaces' })
    ).toBeVisible();
    await page.getByRole('button', { name: 'New Namespace' }).click();
    await page.getByLabel('Name', { exact: true }).fill('staging');
    await page.getByLabel('Description').fill('Staging Namespace');
    await page.getByRole('button', { name: 'Create' }).click();
    await expect(
      page.getByText('Successfully created namespace')
    ).toBeVisible();
  });

  test('can switch to newly created namespace', async ({ page }) => {
    await page.getByRole('link', { name: 'logo' }).click();
    await page.getByRole('button', { name: 'Default' }).click();
    await page.getByText('staging').click();
    await expect(page.getByRole('heading', { name: 'Flags' })).toBeVisible();
  });

  test('can update namespace', async ({ page }) => {
    await page.getByRole('link', { name: 'Settings' }).click();
    await page.getByRole('link', { name: 'Namespaces' }).click();
    await expect(
      page.getByRole('heading', { name: 'Namespaces' })
    ).toBeVisible();
    await page.getByRole('link', { name: 'staging', exact: true }).click();
    await page.getByLabel('Name', { exact: true }).fill('test');
    await page.getByLabel('Description').fill('Test Namespace');
    await page.getByRole('button', { name: 'Update' }).click();
    await expect(
      page.getByText('Successfully updated namespace')
    ).toBeVisible();
  });

  test('deleting current namespace switches to default namespace', async ({
    page
  }) => {
    await page.getByRole('link', { name: 'logo' }).click();
    await page.getByRole('button', { name: 'Default' }).click();
    await page.getByText('test', { exact: true }).click();
    await page.getByRole('link', { name: 'Settings' }).click();
    await page.getByRole('link', { name: 'Namespaces' }).click();
    await expect(
      page.getByRole('heading', { name: 'Namespaces' })
    ).toBeVisible();
    await page.getByRole('link', { name: 'Delete , test' }).click();
    await page.getByRole('button', { name: 'Delete' }).click();
    await expect(page.getByRole('button', { name: 'Default' })).toBeVisible();
  });

  test('cannot delete default namespace', async ({ page }) => {
    await page.getByRole('link', { name: 'Settings' }).click();
    await page.getByRole('link', { name: 'Namespaces' }).click();
    await expect(
      page.getByRole('heading', { name: 'Namespaces' })
    ).toBeVisible();
    await page.getByText('Delete, default').click();
    // assert that the default namespace is still there even after clicking 'delete'
    await page.getByRole('cell', { name: 'default' }).first().click();
  });

  test('cannot delete namespace with flags', async ({ page }) => {
    await page.getByRole('button', { name: 'Default' }).click();
    await page.getByRole('link', { name: 'Settings' }).click();
    await page.getByRole('link', { name: 'Namespaces' }).click();
    await page.getByRole('button', { name: 'New Namespace' }).click();
    await page.getByLabel('Name', { exact: true }).fill('no delete');
    await page.getByLabel('Description').click();
    await page.getByRole('button', { name: 'Create' }).click();

    await page.getByRole('link', { name: 'Flags' }).click();
    await page.getByRole('button', { name: 'Default' }).click();
    await page.getByText('no delete').click();

    await page.getByRole('button', { name: 'New Flag' }).click();
    await page.getByLabel('Name').fill('foo');
    await page.getByLabel('Description').click();
    await page.getByRole('button', { name: 'Create' }).click();
    await page.getByText('Successfully created flag').click();

    await page.getByRole('link', { name: 'Settings' }).click();
    await page.getByRole('link', { name: 'Namespaces' }).click();
    await page.getByRole('link', { name: 'Delete , no delete' }).click();
    await page.getByRole('button', { name: 'Delete' }).click();
    await expect(
      page.getByText(
        'namespace "no-delete" cannot be deleted; flags must be deleted first'
      )
    ).toBeVisible();
  });
});

